  Theorem open_B_tail : forall fx5 R5 M5, DOP.open_mid R M S p can bs R5 M5 ->
    exists fxE RE ME,
      msteps RSEGS (st fx5 R5 0x1239b4 M5) (st fxE RE 0x121de0 ME)
